from core.connections.edarsahub_writer_connection import open_validated_writer_connection
from core.sql_first.db import get_sql_connection

ALLOWED_TRANSITIONS={1:{2},2:{3,4},4:{2},3:{5},5:{6,3},6:set()}

def _dict(cur,row):
    return dict(zip([d[0] for d in cur.description],row)) if row else None

def _read_one(sql,params=()):
    conn=get_sql_connection(); cur=conn.cursor()
    try:
        cur.execute(sql,params); return _dict(cur,cur.fetchone())
    finally:
        cur.close(); conn.close()

def get_by_id(documento_id):
    return _read_one('SELECT * FROM dbo.Fiscal_DocumentosEmitidos WHERE DocumentoFiscalEmitidoID=%s',(documento_id,))

def get_by_uuid(uuid):
    return _read_one('SELECT * FROM dbo.Fiscal_DocumentosEmitidos WHERE UUID=%s',(uuid,))

def list_documents(empresa_id=None,unidad_negocio_id=None,cliente_id=None,venta_id=None,estatus_id=None,limit=100):
    pairs=[('EmpresaID',empresa_id),('UnidadNegocioID',unidad_negocio_id),('ClienteID',cliente_id),('VentaID',venta_id),('EstatusDocumentoFiscalEmitidoID',estatus_id)]
    clauses=[]; params=[]
    for col,val in pairs:
        if val is not None: clauses.append(col+'=%s'); params.append(val)
    where=(' WHERE '+' AND '.join(clauses)) if clauses else ''
    conn=get_sql_connection(); cur=conn.cursor()
    try:
        cur.execute(f'SELECT TOP ({int(limit)}) * FROM dbo.Fiscal_DocumentosEmitidos{where} ORDER BY DocumentoFiscalEmitidoID DESC',tuple(params))
        cols=[d[0] for d in cur.description]; return [dict(zip(cols,r)) for r in cur.fetchall()]
    finally:
        cur.close(); conn.close()

def _exists(cur,table,column,value):
    cur.execute(f'SELECT 1 FROM dbo.{table} WHERE {column}=%s',(value,)); return cur.fetchone() is not None

def create_document(p,actor):
    uuid=(p.get('uuid') or '').strip() or None
    if uuid:
        old=get_by_uuid(uuid)
        if old: return old
    conn,_=open_validated_writer_connection(); cur=conn.cursor()
    try:
        for table,column,value,error in [('Sistema_Empresas','EmpresaID',p['empresa_id'],'EMPRESA_NOT_FOUND'),('Unidades_Negocio','id',p['unidad_negocio_id'],'UNIDAD_NEGOCIO_NOT_FOUND'),('Cliente_Catalogo','ClienteID',p['cliente_id'],'CLIENTE_NOT_FOUND'),('Fiscal_DocumentosEmitidosEstatus','EstatusDocumentoFiscalEmitidoID',p['estatus_id'],'ESTATUS_NOT_FOUND')]:
            if not _exists(cur,table,column,value): raise ValueError(error)
        if p.get('venta_id') is not None and not _exists(cur,'Venta_Encabezado','VentaID',p['venta_id']): raise ValueError('VENTA_NOT_FOUND')
        cur.execute('INSERT INTO dbo.Fiscal_DocumentosEmitidos (EmpresaID,UnidadNegocioID,ClienteID,VentaID,EstatusDocumentoFiscalEmitidoID,UUID,CreadoPor) OUTPUT INSERTED.DocumentoFiscalEmitidoID VALUES (%s,%s,%s,%s,%s,%s,%s)',(p['empresa_id'],p['unidad_negocio_id'],p['cliente_id'],p.get('venta_id'),p['estatus_id'],uuid,actor))
        new_id=int(cur.fetchone()[0]); conn.commit()
    except Exception:
        conn.rollback(); raise
    finally:
        cur.close(); conn.close()
    return get_by_id(new_id)

def transition_document(documento_id,nuevo,actor,fecha_cancelacion=None):
    conn,_=open_validated_writer_connection(); cur=conn.cursor()
    try:
        cur.execute('SELECT EstatusDocumentoFiscalEmitidoID FROM dbo.Fiscal_DocumentosEmitidos WITH (UPDLOCK,HOLDLOCK) WHERE DocumentoFiscalEmitidoID=%s',(documento_id,)); row=cur.fetchone()
        if not row: raise ValueError('DOCUMENT_NOT_FOUND')
        actual=int(row[0])
        if nuevo==actual: conn.rollback(); return get_by_id(documento_id)
        if nuevo not in ALLOWED_TRANSITIONS.get(actual,set()): raise ValueError('INVALID_STATUS_TRANSITION')
        if nuevo==6 and fecha_cancelacion is None: raise ValueError('FECHA_CANCELACION_REQUIRED')
        cur.execute('UPDATE dbo.Fiscal_DocumentosEmitidos SET EstatusDocumentoFiscalEmitidoID=%s,FechaCancelacion=CASE WHEN %s=6 THEN %s ELSE FechaCancelacion END,ModificadoPor=%s,FechaModificacion=SYSUTCDATETIME() WHERE DocumentoFiscalEmitidoID=%s',(nuevo,nuevo,fecha_cancelacion,actor,documento_id)); conn.commit()
    except Exception:
        conn.rollback(); raise
    finally:
        cur.close(); conn.close()
    return get_by_id(documento_id)

def link_to_coa(documento_id,expediente_id,actor):
    conn,_=open_validated_writer_connection(); cur=conn.cursor()
    try:
        if not _exists(cur,'Fiscal_DocumentosEmitidos','DocumentoFiscalEmitidoID',documento_id): raise ValueError('DOCUMENT_NOT_FOUND')
        if not _exists(cur,'COA_Expedientes','ExpedienteID',expediente_id): raise ValueError('EXPEDIENTE_NOT_FOUND')
        cur.execute('SELECT ReferenciaID FROM dbo.COA_ExpedienteReferencias WITH (UPDLOCK,HOLDLOCK) WHERE ExpedienteID=%s AND DocumentoFiscalEmitidoID=%s',(expediente_id,documento_id)); row=cur.fetchone()
        if row: conn.rollback(); return {'referencia_id':int(row[0]),'created':False}
        cur.execute('INSERT INTO dbo.COA_ExpedienteReferencias (ExpedienteID,DocumentoFiscalEmitidoID,CreadoPor) OUTPUT INSERTED.ReferenciaID VALUES (%s,%s,%s)',(expediente_id,documento_id,actor)); ref=int(cur.fetchone()[0]); conn.commit(); return {'referencia_id':ref,'created':True}
    except Exception:
        conn.rollback(); raise
    finally:
        cur.close(); conn.close()

from fastapi import APIRouter,Depends,HTTPException,Query
from core.security import get_current_user
from . import repository
from .schemas import DocumentoCreate,DocumentoTransition,DocumentoLink

router=APIRouter(prefix='/coa/fiscal/documentos-emitidos',tags=['COA - CFDI emitidos'])

def _actor(user):
    for k in ('UsuarioID','usuario_id','id','user_id'):
        if user.get(k) is not None: return int(user[k])
    raise HTTPException(403,'USER_ID_REQUIRED')

@router.get('')
def listar(empresa_id:int|None=None,unidad_negocio_id:str|None=None,cliente_id:int|None=None,venta_id:int|None=None,estatus_id:int|None=None,limit:int=Query(100,ge=1,le=500),_user=Depends(get_current_user)):
    return repository.list_documents(empresa_id,unidad_negocio_id,cliente_id,venta_id,estatus_id,limit)

@router.get('/uuid/{uuid}')
def por_uuid(uuid:str,_user=Depends(get_current_user)):
    row=repository.get_by_uuid(uuid)
    if not row: raise HTTPException(404,'DOCUMENT_NOT_FOUND')
    return row

@router.get('/{documento_id}')
def por_id(documento_id:int,_user=Depends(get_current_user)):
    row=repository.get_by_id(documento_id)
    if not row: raise HTTPException(404,'DOCUMENT_NOT_FOUND')
    return row

@router.post('')
def crear(payload:DocumentoCreate,user=Depends(get_current_user)):
    try: return repository.create_document(payload.model_dump(),_actor(user))
    except ValueError as e: raise HTTPException(409,str(e))

@router.post('/{documento_id}/transiciones')
def transicionar(documento_id:int,payload:DocumentoTransition,user=Depends(get_current_user)):
    try: return repository.transition_document(documento_id,payload.nuevo_estatus_id,_actor(user),payload.fecha_cancelacion)
    except ValueError as e: raise HTTPException(404 if str(e)=='DOCUMENT_NOT_FOUND' else 409,str(e))

@router.post('/{documento_id}/coa-referencias')
def vincular(documento_id:int,payload:DocumentoLink,user=Depends(get_current_user)):
    try: return repository.link_to_coa(documento_id,payload.expediente_id,_actor(user))
    except ValueError as e: raise HTTPException(404 if str(e) in {'DOCUMENT_NOT_FOUND','EXPEDIENTE_NOT_FOUND'} else 409,str(e))
